const INVALID:f64=-1e300;
fn isOp(c:u8)bool{return c=='+' or c=='-' or c=='*' or c=='/';}
export fn prefix_evaluation(v:[*c]const i64,n:usize)f64{if(v==null or n<2 or n>63 or v[0]<1 or v[0]>62 or n!=@as(usize,@intCast(v[0]))+1)return INVALID;var tokens:[31]u8=undefined;var count:usize=0;var need=true;for(1..n)|i|{if(v[i]<0 or v[i]>127)return INVALID;const c:u8=@intCast(v[i]);if(c==' '){if(need)return INVALID;need=true;continue;}if(!(isOp(c) or (c>='0' and c<='9')) or !need or count>=31)return INVALID;tokens[count]=c;count+=1;need=false;}if(need or count==0)return INVALID;var stack:[31]f64=undefined;var top:usize=0;var p=count;while(p>0){p-=1;const c=tokens[p];if(c>='0' and c<='9'){stack[top]=@floatFromInt(c-'0');top+=1;continue;}if(top<2)return INVALID;top-=1;const a=stack[top];top-=1;const b=stack[top];var result:f64=0;if(c=='+')result=a+b else if(c=='-')result=a-b else if(c=='*')result=a*b else{if(b==0)return INVALID;result=a/b;}stack[top]=result;top+=1;}return if(top==1 and std.math.isFinite(stack[0])) stack[0] else INVALID;}
const std=@import("std");
